import json
from datetime import datetime

def endpoint_key(src, dst):
    return (src, dst)

with open('eve.jsonl', encoding='utf-8') as f:
    alerts = [json.loads(line) for line in f if line.strip()]
for event in alerts:
    if event.get('event_type') == 'alert':
        print(endpoint_key(event.get('src_ip'), event.get('dest_ip')))

finding = {
    'question': 'What communication was observed?',
    'observations': ['Packet 184: TCP SYN A -> B:443', 'Packet 186: TCP SYN/ACK B -> A'],
    'interpretation': 'The trace supports an observed TCP connection establishment sequence.',
    'limitation': 'The trace alone does not establish user identity or application intent.'
}
for k,v in finding.items():
    print(k + ':', v)
